/**
 * Action 05: 優先度順に整理した朝会資料を自動生成
 *
 * tx_1_imp_1 エージェントの第5アクション
 * 優先度付けされた課題リストから、朝会用の資料を自動生成する
 */

export const ACTION_05_PROMPT_VERSION = "1.0.0";

export interface Action05Input {
  prioritizedIssues: Array<{
    id: string;
    title: string;
    description: string;
    priority: number;
    severity: "critical" | "high" | "medium" | "low";
    category: string;
    reportedBy: string;
    reportedAt: string;
    relatedIssues?: string[];
  }>;
  meetingDate: string;
  departmentName: string;
  attendees: string[];
}

export interface Action05Output {
  materialId: string;
  title: string;
  generatedAt: string;
  sections: Array<{
    sectionType: "executive_summary" | "critical_issues" | "action_items" | "metrics" | "appendix";
    content: string;
    issueCount?: number;
  }>;
  estimatedMeetingDuration: number;
  notificationStatus: "pending" | "sent" | "failed";
}

export function buildAction05Prompt(input: Action05Input): string {
  const issuesSummary = input.prioritizedIssues
    .slice(0, 10)
    .map(
      (issue, idx) =>
        `${idx + 1}. [${issue.severity.toUpperCase()}] ${issue.title} (優先度: ${issue.priority}) - ${issue.category}`
    )
    .join("\n");

  const prompt = `
あなたは朝会資料生成エージェントです。以下の優先度付けされた課題リストから、部長が朝会で使用する資料を自動生成してください。

【入力データ】
- 会議日: ${input.meetingDate}
- 部門: ${input.departmentName}
- 参加者: ${input.attendees.join(", ")}
- 優先度付け済み課題数: ${input.prioritizedIssues.length}件

【優先度付け済み課題（上位10件）】
${issuesSummary}

【生成要件】
1. エグゼクティブサマリー（1-2分で読める要約）
2. 重大課題セクション（即座の対応が必要な課題）
3. アクションアイテム（本日中に実施すべき項目）
4. メトリクス（課題件数、カテゴリ別分布、解決期間など）
5. 付録（詳細データ、参考情報）

【出力形式】
JSON形式で以下の構造で返してください：
{
  "materialId": "string (UUID形式)",
  "title": "string (朝会資料のタイトル)",
  "generatedAt": "ISO8601形式のタイムスタンプ",
  "sections": [
    {
      "sectionType": "executive_summary|critical_issues|action_items|metrics|appendix",
      "content": "string (セクションの内容)",
      "issueCount": "number (該当課題数、該当する場合のみ)"
    }
  ],
  "estimatedMeetingDuration": "number (推定会議時間（分）)",
  "notificationStatus": "pending"
}

【注意事項】
- 資料は部長が朝会で即座に使用できる形式にしてください
- 重大課題は必ず最初に配置してください
- 各セクションは簡潔で、要点を明確にしてください
- 推定会議時間は課題数と複雑度から算出してください
`;

  return prompt;
}
